extension OrlaMood {
    /// Which eye and bubble each mood uses. From ORLA_MOODS in finn8.js.
    var pixelLook: OrlaLook {
        switch self {
        case .calm:
            return OrlaLook(eye: "normal", icon: nil)
        case .thinking:
            return OrlaLook(eye: "up", icon: "^")
        case .asking:
            return OrlaLook(eye: "normal", icon: "?")
        case .hinting:
            return OrlaLook(eye: "normal", icon: "bulb")
        case .pleased:
            return OrlaLook(eye: "happy", icon: "*")
        }
    }
}

extension FishMood {
    /// Which eye, mouth, bubble and extras each mood uses. From MOODS in finn8.js.
    var pixelLook: PixelLook {
        switch self {
        case .happy:
            return PixelLook(eye: "normal", mouth: "smile", icon: nil, cap: false, lens: false, headband: false)
        case .curious:
            return PixelLook(eye: "wide", mouth: "open", icon: "!", cap: false, lens: false, headband: false)
        case .listening:
            return PixelLook(eye: "down", mouth: "smile", icon: nil, cap: false, lens: false, headband: false)
        case .thinking:
            return PixelLook(eye: "up", mouth: "flat", icon: "^", cap: false, lens: false, headband: false)
        case .proud:
            return PixelLook(eye: "happy", mouth: "open", icon: "*", cap: false, lens: false, headband: false)
        case .confused:
            return PixelLook(eye: "small", mouth: "flat", icon: "?", cap: false, lens: false, headband: false)
        case .shrug:
            return PixelLook(eye: "up", mouth: "open", icon: " ", cap: false, lens: false, headband: false)
        case .forgetful:
            return PixelLook(eye: "half", mouth: "open", icon: "~", cap: false, lens: false, headband: false)
        case .inspecting:
            return PixelLook(eye: "down", mouth: "flat", icon: nil, cap: false, lens: true, headband: false)
        case .graduate:
            return PixelLook(eye: "happy", mouth: "open", icon: "*", cap: true, lens: false, headband: false)
        case .focused:
            return PixelLook(eye: "focus", mouth: "flat", icon: nil, cap: false, lens: false, headband: true)
        case .sleepy:
            return PixelLook(eye: "shut", mouth: "smile", icon: "Z", cap: false, lens: false, headband: false)
        }
    }
}
